<?php $title="Smart Inventory";require "includes/header.php";$r=$conn->query("SELECT * FROM bicycles ORDER BY stock ASC");$total=$conn->query("SELECT COALESCE(SUM(stock),0)n FROM bicycles")->fetch_assoc()["n"];$low=$conn->query("SELECT COUNT(*)n FROM bicycles WHERE stock<=5")->fetch_assoc()["n"];$val=$conn->query("SELECT COALESCE(SUM(price*stock),0)n FROM bicycles")->fetch_assoc()["n"];?><div class="hero"><div class="orb"></div><h1>📦 Smart Inventory</h1><p>AI-style low-stock and restock intelligence.</p></div><div class="grid four"><div class="card kpi"><div class="label">Units</div><div class="value"><?=$total?></div></div><div class="card kpi"><div class="label">Low Stock</div><div class="value"><?=$low?></div></div><div class="card kpi"><div class="label">Models</div><div class="value"><?=$conn->query("SELECT COUNT(*)n FROM bicycles")->fetch_assoc()["n"]?></div></div><div class="card kpi"><div class="label">Stock Value</div><div class="value"><?=money($val)?></div></div></div><div class="card" style="margin-top:16px"><table><tr><th>Model</th><th>Category</th><th>Stock</th><th>AI Action</th></tr><?php while($x=$r->fetch_assoc()):?><tr><td><?=e($x["name"])?></td><td><?=e($x["category"])?></td><td><?=$x["stock"]?></td><td><?php if($x["stock"]<=3):?><span class="badge red">Restock Now</span><?php elseif($x["stock"]<=5):?><span class="badge warn">Watch</span><?php else:?><span class="badge">Healthy</span><?php endif;?></td></tr><?php endwhile;?></table></div><?php require "includes/footer.php";?>